export const getAnalyzeMessageUrl = (id: string,) => {




  return `/api/email/messages/${id}/ai-analysis`
}

/**
 * @summary Run AI analysis on a message
 */
export const analyzeMessage = async (id: string,
    aiAnalysisRequest?: AiAnalysisRequest, options?: RequestInit): Promise<AiAnalysis> => {

  return customFetch<AiAnalysis>(getAnalyzeMessageUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      aiAnalysisRequest,)
  }
);}




